def check(answer, facts):
    rows = facts["rows"]
    seen = set()
    duplicate = False
    for r in rows:
        i = r["id"]
        if i in seen:
            duplicate = True
        seen.add(i)
    if duplicate:
        return answer == {"error": "duplicate"}
    for r in rows:
        if "name" not in r:
            return answer == {"error": "missing_name"}
    ordered = sorted(rows, key=lambda r: r["id"])
    expected = {"rows": [{"id": r["id"], "display_name": r["name"]} for r in ordered]}
    return answer == expected}"}

